{
  "name": "think-ai-auto",
  "version": "1.8.4",
  "description": "一键配置 Claude Code / OpenCode / OpenClaw / Hermes Agent 的 API 密钥工具",
  "type": "module",
  "main": "index.js",
  "bin": {
    "think-ai-auto": "bin/index.js"
  },
  "files": [
    "bin/index.js",
    "README.md",
    "教程.txt"
  ],
  "scripts": {
    "start": "node bin/index.js",
    "test": "node test/openclaw-config.test.mjs && node test/hermes-config.test.mjs"
  },
  "keywords": [
    "claude",
    "opencode",
    "openclaw",
    "hermes",
    "api",
    "config",
    "think"
  ],
  "author": "",
  "license": "MIT",
  "engines": {
    "node": ">=18.0.0"
  },
  "dependencies": {
    "@inquirer/prompts": "^8.2.0",
    "json5": "^2.2.3",
    "yaml": "^2.9.0"
  }
}

#!/usr/bin/env node

import { select, password } from '@inquirer/prompts';
import fs from 'fs';
import path from 'path';
import os from 'os';
import { pathToFileURL } from 'url';
import JSON5 from 'json5';
import YAML from 'yaml';

const API_BASE_URL = 'https://www.thinkai.tv';
const THINKAI_MODELS_URL = `${API_BASE_URL}/v1/models`;
const OPENCLAW_ANTHROPIC_PROVIDER = 'think-Anthropic';
const OPENCLAW_OPENAI_PROVIDER = 'think-Openai';
const OPENCLAW_DEFAULT_CONTEXT_WINDOW = 200000;
const OPENCLAW_DEFAULT_MAX_TOKENS = 8192;
const HERMES_DEFAULT_CONTEXT_LENGTH = 200000;
const HERMES_API_MODE = 'chat_completions';

const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m',
  bold: '\x1b[1m'
};

function colorize(text, color) {
  return `${colors[color] || ''}${text}${colors.reset}`;
}

function getHomeDir() {
  return os.homedir();
}

function ensureDir(dirPath) {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }
}

function getTimestamp() {
  const now = new Date();
  return now.toISOString().replace(/[:.]/g, '-').replace('T', '_').slice(0, 19);
}

function backupFile(filePath) {
  if (fs.existsSync(filePath)) {
    const timestamp = getTimestamp();
    const backupPath = `${filePath}.bak.${timestamp}`;
    fs.copyFileSync(filePath, backupPath);
    console.log(`📦 已备份原配置: ${backupPath}`);
    return true;
  }
  return false;
}

function readJsonFile(filePath) {
  try {
    if (fs.existsSync(filePath)) {
      const content = fs.readFileSync(filePath, 'utf-8');
      return JSON.parse(content);
    }
  } catch (e) {}
  return {};
}

function isPlainObject(value) {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function resolveUserPath(filePath, homeDir = getHomeDir()) {
  if (filePath === '~') {
    return homeDir;
  }
  if (filePath.startsWith(`~${path.sep}`) || filePath.startsWith('~/')) {
    return path.join(homeDir, filePath.slice(2));
  }
  return path.resolve(filePath);
}

export function isDirectCliRun(moduleUrl = import.meta.url, argvPath = process.argv[1]) {
  if (!argvPath) {
    return false;
  }

  let executablePath = argvPath;
  try {
    executablePath = fs.realpathSync(argvPath);
  } catch (err) {
    executablePath = path.resolve(argvPath);
  }

  return moduleUrl === pathToFileURL(executablePath).href;
}

export function resolveOpenClawConfigPath(env = process.env, homeDir = getHomeDir()) {
  const configuredPath = env.OPENCLAW_CONFIG_PATH?.trim();
  if (configuredPath) {
    return resolveUserPath(configuredPath, homeDir);
  }
  return path.join(homeDir, '.openclaw', 'openclaw.json');
}

export function resolveHermesConfigPath(env = process.env, homeDir = getHomeDir()) {
  const hermesHome = env.HERMES_HOME?.trim()
    ? resolveUserPath(env.HERMES_HOME.trim(), homeDir)
    : path.join(homeDir, '.hermes');
  return path.join(hermesHome, 'config.yaml');
}

export function readOpenClawConfigFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  try {
    const parsed = JSON5.parse(fs.readFileSync(filePath, 'utf-8'));
    return isPlainObject(parsed) ? parsed : {};
  } catch (err) {
    throw new Error(`Failed to parse OpenClaw config as JSON5: ${filePath}`, { cause: err });
  }
}

export function readHermesConfigFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  try {
    const parsed = YAML.parse(fs.readFileSync(filePath, 'utf-8'));
    return isPlainObject(parsed) ? parsed : {};
  } catch (err) {
    throw new Error(`Failed to parse Hermes config as YAML: ${filePath}`, { cause: err });
  }
}

function writeJsonFile(filePath, data) {
  ensureDir(path.dirname(filePath));
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf-8');
}

function writeYamlFile(filePath, data) {
  ensureDir(path.dirname(filePath));
  fs.writeFileSync(filePath, YAML.stringify(data, { lineWidth: 0 }), 'utf-8');
}

function deepMerge(target, source) {
  const result = { ...target };
  for (const key of Object.keys(source)) {
    if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      result[key] = deepMerge(result[key] || {}, source[key]);
    } else {
      result[key] = source[key];
    }
  }
  return result;
}

function clonePlainValue(value) {
  if (Array.isArray(value)) {
    return value.map(clonePlainValue);
  }
  if (isPlainObject(value)) {
    return Object.fromEntries(Object.entries(value).map(([key, child]) => [key, clonePlainValue(child)]));
  }
  return value;
}

function normalizeModelIds(modelIds) {
  const seen = new Set();
  const normalized = [];

  for (const modelId of modelIds || []) {
    const id = typeof modelId === 'string' ? modelId.trim() : '';
    if (!id || seen.has(id)) {
      continue;
    }
    seen.add(id);
    normalized.push(id);
  }

  return normalized;
}

function createOpenClawModelDefinition(modelId) {
  return {
    "id": modelId,
    "name": modelId,
    "reasoning": false,
    "input": ["text", "image"],
    "cost": { "input": 0, "output": 0, "cacheRead": 0, "cacheWrite": 0 },
    "contextWindow": OPENCLAW_DEFAULT_CONTEXT_WINDOW,
    "maxTokens": OPENCLAW_DEFAULT_MAX_TOKENS
  };
}

function createOpenClawProviderModels(modelIds) {
  return normalizeModelIds(modelIds).map(createOpenClawModelDefinition);
}

function createOpenClawModelRefs(modelIds) {
  const refs = [];
  for (const modelId of normalizeModelIds(modelIds)) {
    refs.push(`${OPENCLAW_ANTHROPIC_PROVIDER}/${modelId}`);
    refs.push(`${OPENCLAW_OPENAI_PROVIDER}/${modelId}`);
  }
  return refs;
}

function createOpenClawModelAllowlist(modelIds) {
  return Object.fromEntries(createOpenClawModelRefs(modelIds).map((ref) => [ref, {}]));
}

function parseThinkAiError(body) {
  if (typeof body === 'string') {
    return body.trim();
  }
  if (typeof body?.error?.message === 'string') {
    return body.error.message;
  }
  if (typeof body?.message === 'string') {
    return body.message;
  }
  return '';
}

async function readResponseJson(response) {
  const text = await response.text();
  if (!text.trim()) {
    return {};
  }

  try {
    return JSON.parse(text);
  } catch (err) {
    throw new Error('获取 thinkAI 模型列表失败: 响应不是有效 JSON');
  }
}

export async function fetchThinkAiModels(apiKey, fetchImpl = globalThis.fetch) {
  if (typeof fetchImpl !== 'function') {
    throw new Error('当前 Node.js 环境不支持 fetch，请升级到 Node.js 18 或更高版本。');
  }

  let response;
  try {
    response = await fetchImpl(THINKAI_MODELS_URL, {
      headers: {
        "Authorization": `Bearer ${apiKey}`,
        "Accept": "application/json"
      }
    });
  } catch (err) {
    throw new Error(`获取 thinkAI 模型列表失败: ${err.message}`);
  }

  const body = await readResponseJson(response);
  if (!response.ok) {
    const message = parseThinkAiError(body) || response.statusText || '未知错误';
    throw new Error(`获取 thinkAI 模型列表失败 (${response.status}): ${message}`);
  }

  if (!Array.isArray(body?.data)) {
    throw new Error('获取 thinkAI 模型列表失败: 响应缺少 data 数组');
  }

  const modelIds = normalizeModelIds(body.data.map((model) => model?.id));
  if (modelIds.length === 0) {
    throw new Error('获取 thinkAI 模型列表失败: 模型列表为空');
  }

  return modelIds;
}

function normalizeOpenClawStreamingMode(value) {
  if (typeof value === 'string' && value.trim()) {
    return value.trim();
  }
  if (typeof value === 'boolean') {
    return value ? 'partial' : 'off';
  }
  return undefined;
}

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function migrateTelegramStreamingNode(node) {
  if (!isPlainObject(node)) {
    return node;
  }

  const migrated = { ...node };
  const existingStreaming = migrated.streaming;
  const streaming = isPlainObject(existingStreaming) ? clonePlainValue(existingStreaming) : {};
  const scalarMode = isPlainObject(existingStreaming)
    ? undefined
    : normalizeOpenClawStreamingMode(existingStreaming);
  const streamMode = normalizeOpenClawStreamingMode(migrated.streamMode);

  if (!hasOwn(streaming, 'mode')) {
    if (scalarMode) {
      streaming.mode = scalarMode;
    } else if (streamMode) {
      streaming.mode = streamMode;
    }
  }

  if (hasOwn(migrated, 'chunkMode') && !hasOwn(streaming, 'chunkMode')) {
    streaming.chunkMode = migrated.chunkMode;
  }

  if (hasOwn(migrated, 'draftChunk')) {
    const preview = isPlainObject(streaming.preview) ? clonePlainValue(streaming.preview) : {};
    if (!hasOwn(preview, 'chunk')) {
      preview.chunk = clonePlainValue(migrated.draftChunk);
    }
    streaming.preview = preview;
  }

  if (hasOwn(migrated, 'blockStreaming') || hasOwn(migrated, 'blockStreamingCoalesce')) {
    const block = isPlainObject(streaming.block) ? clonePlainValue(streaming.block) : {};
    if (hasOwn(migrated, 'blockStreaming') && !hasOwn(block, 'enabled')) {
      block.enabled = migrated.blockStreaming;
    }
    if (hasOwn(migrated, 'blockStreamingCoalesce') && !hasOwn(block, 'coalesce')) {
      block.coalesce = clonePlainValue(migrated.blockStreamingCoalesce);
    }
    streaming.block = block;
  }

  if (Object.keys(streaming).length > 0) {
    migrated.streaming = streaming;
  }

  delete migrated.streamMode;
  delete migrated.chunkMode;
  delete migrated.blockStreaming;
  delete migrated.draftChunk;
  delete migrated.blockStreamingCoalesce;

  return migrated;
}

export function migrateOpenClawLegacyConfig(config) {
  const migrated = clonePlainValue(isPlainObject(config) ? config : {});
  const telegram = migrated.channels?.telegram;
  if (!isPlainObject(telegram)) {
    return migrated;
  }

  migrated.channels.telegram = migrateTelegramStreamingNode(telegram);
  const accounts = migrated.channels.telegram.accounts;
  if (isPlainObject(accounts)) {
    migrated.channels.telegram.accounts = Object.fromEntries(
      Object.entries(accounts).map(([accountId, accountConfig]) => [
        accountId,
        migrateTelegramStreamingNode(accountConfig)
      ])
    );
  }

  return migrated;
}

function createOpenClawConfig(apiKey, modelIds, primaryModel) {
  const normalizedModelIds = normalizeModelIds(modelIds);
  if (normalizedModelIds.length === 0) {
    throw new Error('OpenClaw 模型列表为空，无法生成配置');
  }

  const allowlist = createOpenClawModelAllowlist(normalizedModelIds);
  if (!Object.prototype.hasOwnProperty.call(allowlist, primaryModel)) {
    throw new Error(`OpenClaw 默认模型不在模型列表中: ${primaryModel || '未设置'}`);
  }

  return {
    "models": {
      "providers": {
        [OPENCLAW_ANTHROPIC_PROVIDER]: {
          "baseUrl": API_BASE_URL,
          "apiKey": apiKey,
          "api": "anthropic-messages",
          "models": createOpenClawProviderModels(normalizedModelIds)
        },
        [OPENCLAW_OPENAI_PROVIDER]: {
          "baseUrl": `${API_BASE_URL}/v1`,
          "apiKey": apiKey,
          "api": "openai-completions",
          "models": createOpenClawProviderModels(normalizedModelIds)
        }
      }
    },
    "agents": {
      "defaults": {
        "model": { "primary": primaryModel },
        "models": allowlist
      }
    }
  };
}

export function buildOpenClawConfig(existing, apiKey, modelIds, primaryModel) {
  return deepMerge(migrateOpenClawLegacyConfig(existing), createOpenClawConfig(apiKey, modelIds, primaryModel));
}

function normalizeProviderId(providerId) {
  return typeof providerId === 'string' ? providerId.trim().toLowerCase() : '';
}

export function findOpenClawProvider(config, providerId) {
  const providers = config?.models?.providers;
  if (!isPlainObject(providers)) {
    return undefined;
  }

  const expected = normalizeProviderId(providerId);
  const entry = Object.entries(providers).find(([key]) => normalizeProviderId(key) === expected);
  return entry?.[1];
}

function getOpenClawProviderModelIds(provider) {
  if (!Array.isArray(provider?.models)) {
    return [];
  }
  return normalizeModelIds(provider.models.map((model) => model?.id));
}

export function getOpenClawModelStatus(config) {
  const anthropicProvider = findOpenClawProvider(config, OPENCLAW_ANTHROPIC_PROVIDER);
  const openaiProvider = findOpenClawProvider(config, OPENCLAW_OPENAI_PROVIDER);
  const anthropicModelIds = getOpenClawProviderModelIds(anthropicProvider);
  const openaiModelIds = getOpenClawProviderModelIds(openaiProvider);
  const configuredModelRefs = isPlainObject(config?.agents?.defaults?.models)
    ? config.agents.defaults.models
    : {};
  const expectedModelRefs = [
    ...anthropicModelIds.map((modelId) => `${OPENCLAW_ANTHROPIC_PROVIDER}/${modelId}`),
    ...openaiModelIds.map((modelId) => `${OPENCLAW_OPENAI_PROVIDER}/${modelId}`)
  ];
  const missingModelRefs = expectedModelRefs.filter(
    (ref) => !Object.prototype.hasOwnProperty.call(configuredModelRefs, ref)
  );
  const primaryModel = config?.agents?.defaults?.model?.primary;
  const primaryInAllowlist = !!primaryModel && Object.prototype.hasOwnProperty.call(configuredModelRefs, primaryModel);

  return {
    primaryModel,
    primaryInAllowlist,
    expectedModelRefs,
    missingModelRefs,
    anthropicModelCount: anthropicModelIds.length,
    openaiModelCount: openaiModelIds.length
  };
}

function createHermesConfig(apiKey, modelId) {
  const normalizedModelId = typeof modelId === 'string' ? modelId.trim() : '';
  if (!normalizedModelId) {
    throw new Error('Hermes Agent 默认模型不能为空');
  }

  return {
    "model": {
      "provider": "custom",
      "default": normalizedModelId,
      "base_url": `${API_BASE_URL}/v1`,
      "api_key": apiKey,
      "api_mode": HERMES_API_MODE,
      "context_length": HERMES_DEFAULT_CONTEXT_LENGTH
    }
  };
}

export function buildHermesConfig(existing, apiKey, modelId) {
  const result = clonePlainValue(isPlainObject(existing) ? existing : {});
  result.model = createHermesConfig(apiKey, modelId).model;
  return result;
}

export function getHermesModelStatus(config) {
  const model = isPlainObject(config?.model) ? config.model : {};
  const provider = typeof model.provider === 'string' ? model.provider : undefined;
  const defaultModel = typeof model.default === 'string' ? model.default : undefined;
  const baseUrl = typeof model.base_url === 'string' ? model.base_url : undefined;
  const apiKeyConfigured = typeof model.api_key === 'string' && model.api_key.length > 0;
  const apiMode = typeof model.api_mode === 'string' ? model.api_mode : undefined;
  const contextLength = Number.isFinite(model.context_length) ? model.context_length : undefined;
  const ready = provider === 'custom' &&
    !!defaultModel &&
    baseUrl === `${API_BASE_URL}/v1` &&
    apiKeyConfigured &&
    apiMode === HERMES_API_MODE &&
    contextLength >= 64000;

  return {
    provider,
    defaultModel,
    baseUrl,
    apiKeyConfigured,
    apiMode,
    contextLength,
    ready
  };
}

function configureClaudeCode(apiKey) {
  const homeDir = getHomeDir();
  const claudeJsonPath = path.join(homeDir, '.claude.json');
  backupFile(claudeJsonPath);
  const claudeJson = readJsonFile(claudeJsonPath);
  claudeJson.hasCompletedOnboarding = true;
  writeJsonFile(claudeJsonPath, claudeJson);
  console.log(`✓ 已初始化: ${claudeJsonPath}`);

  const settingsPath = path.join(homeDir, '.claude', 'settings.json');
  backupFile(settingsPath);
  const settings = readJsonFile(settingsPath);
  settings.env = {
    ...(settings.env || {}),
    ANTHROPIC_BASE_URL: API_BASE_URL,
    API_TIMEOUT_MS: 3000000,
    ANTHROPIC_AUTH_TOKEN: apiKey,
    ANTHROPIC_API_KEY: apiKey
  };
  writeJsonFile(settingsPath, settings);
  console.log(`✓ 已配置: ${settingsPath}`);
  console.log('\n🎉 Claude Code 配置完成！');
}

function readTomlValue(content, key) {
  const match = content.match(new RegExp(`^${key}\\s*=\\s*"([^"]*)"`, 'm'));
  return match ? match[1] : null;
}

function mergeTomlConfig(existing, name, baseUrl, apiKey) {
