async function main() {
  console.log('╔════════════════════════════════════════╗');
  console.log('║     think AI 配置工具                ║');
  console.log('║     API: https://www.thinkai.tv          ║');
  console.log('╚════════════════════════════════════════╝\n');

  const tool = await select({
    message: '请选择要配置的工具 (上下箭头选择):',
    choices: [
      { name: 'Claude Code', value: 'claude-code' },
      { name: 'OpenCode', value: 'opencode' },
      { name: 'OpenClaw', value: 'openclaw' },
      { name: 'Hermes Agent', value: 'hermes-agent' },
      { name: 'Codex', value: 'codex' }
    ],
    default: 'claude-code'
  });

  const apiKey = await password({
    message: '请输入/粘贴您的 API 令牌:',
    mask: '*',
    validate: (input) => {
      if (!input || input.trim().length === 0) {
        return '令牌不能为空';
      }
      return true;
    }
  });

  const trimmedKey = apiKey.trim();

  switch (tool) {
    case 'claude-code':
      configureClaudeCode(trimmedKey);
      break;
    case 'opencode':
      configureOpenCode(trimmedKey);
      break;
    case 'openclaw':
      await configureOpenClaw(trimmedKey);
      break;
    case 'hermes-agent':
      await configureHermesAgent(trimmedKey);
      break;
    case 'codex':
      configureCodex(trimmedKey);
      break;
  }
}

